  glossary_en = jsonb_build_array(
    jsonb_build_object('term', $$Luck and risk$$, 'body', $$The invisible role that forces outside an individual's control play in every financial outcome, easily overlooked from the outside.$$),
    jsonb_build_object('term', $$Never enough$$, 'body', $$The tendency for the goalposts of "enough" money or status to keep moving outward every time they are reached.$$),
    jsonb_build_object('term', $$Compounding$$, 'body', $$Growth that builds on previously earned growth, with the majority of eventual value arriving late, after decades of quiet accumulation.$$),
    jsonb_build_object('term', $$Room for error$$, 'body', $$Deliberately planning for your own assumptions to be wrong, so a single bad year or miscalculation cannot force you out of the game.$$),
    jsonb_build_object('term', $$Tail events$$, 'body', $$The small number of extreme outcomes that end up accounting for a disproportionate share of total results.$$),
    jsonb_build_object('term', $$Rich vs. wealthy$$, 'body', $$Rich is visible current spending; wealthy is unspent financial assets, which are by nature hidden from view.$$),
    jsonb_build_object('term', $$Reasonable over rational$$, 'body', $$Favoring the financial strategy you can realistically sustain through good years and bad over a technically optimal one you might abandon.$$),
    jsonb_build_object('term', $$Cost of admission$$, 'body', $$Treating market volatility and downturns as the routine price paid for long-run investment gains, not as an unexpected penalty.$$)
