    jsonb_build_object('label', $$ຫຼັກຖານແມ່ນເລື່ອງເລົ່າ ບໍ່ແມ່ນການຄົ້ນຄວ້າ.$$, 'body', $$Carnegie ອີງໃສ່ເລື່ອງລາວຈາກນັກຮຽນ, ຄູ່ຄ້າທາງທຸລະກິດ ແລະ ບຸກຄົນປະຫວັດສາດຂອງລາວເອງ ບວກກັບປະສົບການຫຼາຍປີໃນການສອນຫຼັກສູດເວົ້າຕໍ່ໜ້າສາທາລະນະ. ຕົວຢ່າງເຫຼົ່ານີ້ ມັກໜ້າຈື່ ແລະ ໃຫ້ຄວາມຮູ້ແທ້ໆ ແຕ່ບໍ່ແມ່ນຫຼັກຖານທີ່ຄວບຄຸມໄດ້ ແລະ ບາງເຫດການປະຫວັດສາດ ແລະ ລາຍລະອຽດຍຸກສະໄໝ ສະທ້ອນຄວາມເຊື່ອຂອງວັດທະນະທຳທຸລະກິດອາເມຣິກາຕົ້ນສະຕະວັດທີ 20 ຫຼາຍກວ່າໂມເດວການຊັກຈູງທີ່ເປັນສາກົນ ຫຼື ຖືກທົດສອບຢ່າງເຄັ່ງຄັດ.$$),
    jsonb_build_object('label', $$ຄວາມຈິງໃຈ ຄືເງື່ອນໄຂຫຼັກ ແລະ ມັນງ່າຍທີ່ຈະຂ້າມຜ່ານໂດຍບໍ່ສັງເກດ.$$, 'body', $$Carnegie ຢ້ຳຫຼາຍຄັ້ງວ່າ ເຕັກນິກເຫຼົ່ານີ້ຈະໄດ້ຜົນໃນໄລຍະຍາວ ກໍ່ຕໍ່ເມື່ອຄວາມສົນໃຈຕໍ່ຄົນເປັນຄວາມຈິງໃຈເທົ່ານັ້ນ — ຄຳປໍ້ຍໍ, ການຮັບຟັງແບບປອມ ແລະ ຄຳຊົມທີ່ສະແດງອອກ ຈະຖືກຈັບໄດ້ ແລະ ທຳລາຍຄວາມໄວ້ວາງໃຈໄວກວ່າການບໍ່ເວົ້າຫຍັງເລີຍ. ຜູ້ອ່ານທີ່ຟ້າວ ອາດຮັບເອົາເຕັກນິກເປັນສະຄຣິບ ແລ້ວພາດຈຸດວ່າ ລະບົບທັງໝົດຈະລົ້ມ ຖ້າບໍ່ມີຄວາມຈິງໃຈແທ້ໆຢູ່ເບື້ອງຫຼັງ.$$),
    jsonb_build_object('label', $$ຖ້າໃຊ້ດ້ວຍຄວາມສະຫຼາດແກມໂກງ ເຕັກນິກດຽວກັນນີ້ຈະກາຍເປັນການຫຼອກລວງ.$$, 'body', $$ເກືອບທຸກຫຼັກການໃນປຶ້ມ — ການປຸກຄວາມຢາກຢ່າງແຮງກ້າ, ການໃຫ້ຄົນຮູ້ສຶກວ່າແນວຄິດເປັນຂອງເຂົາເອງ, ການດຶງດູດແຮງຈູງໃຈອັນສູງສົ່ງ — ກໍ່ຄືການອະທິບາຍວິທີຫຼອກລວງຄົນໄປສູ່ຜົນລັບທີ່ເປັນປະໂຫຍດຕໍ່ທ່ານ ໂດຍເສຍປຽບເຂົາ. ປຶ້ມບໍ່ໄດ້ໃຫ້ວິທີທົດສອບທີ່ຊັດເຈນເພື່ອແຍກຄວາມແຕກຕ່າງ — ການຕັດສິນນັ້ນ ຖືກປະໄວ້ໃຫ້ຈັນຍາບັນຂອງຜູ້ອ່ານເອງທັງໝົດ.$$),
    jsonb_build_object('label', $$ການຫຼີກລ່ຽງຄວາມຂັດແຍ້ງ ອາດຖືກຕີຄວາມກວ້າງກວ່າທີ່ຕັ້ງໃຈໄວ້.$$, 'body', $$ຫຼັກການເຊັ່ນ ຢ່າບອກວ່າ "ທ່ານຜິດ" ແລະ ຫຼີກລ່ຽງການໂຕ້ຖຽງ ແມ່ນມຸ້ງໄປທີ່ຄວາມຂັດແຍ້ງທີ່ບໍ່ມີປະໂຫຍດ ແລະ ຂັບເຄື່ອນດ້ວຍອັດຕາຕົວຕົນ ບໍ່ແມ່ນທຸກຄວາມເຫັນຕ່າງທີ່ຄວນເວົ້າອອກມາ. ບາງສະຖານະການແທ້ໆຕ້ອງການການປະທະໂດຍກົງ ແລະ ຊັດເຈນ — ບັນຫາຄວາມປອດໄພ, ການລະເມີດຈັນຍາບັນ, ຄວາມຜິດພາດທາງຂໍ້ເທັດຈິງທີ່ຊັດເຈນ ແລະ ມີຄວາມສ່ຽງແທ້ — ແລະ ການປະຕິບັດການຫຼີກລ່ຽງເປັນກົດສາກົນ ອາດກົດຄວາມເຫັນຕ່າງທີ່ຄວນຖືກເວົ້າອອກມາ.$$),
    jsonb_build_object('label', $$ມາດຕະຖານຄວາມກົງໄປກົງມາທີ່ສົມມຸດຂຶ້ນ ແມ່ນມາຈາກວັດທະນະທຳສະເພາະ.$$, 'body', $$ຄຳແນະນຳຂອງ Carnegie ຖືກສ້າງຂຶ້ນຈາກມາດຕະຖານທຸລະກິດ ແລະ ສັງຄົມອາເມຣິກາຕົ້ນ-ກາງສະຕະວັດທີ 20 ຊຶ່ງບໍ່ຄືກັບມາດຕະຖານລາວ ຫຼື ພາກພື້ນທົ່ວໄປ ກ່ຽວກັບລຳດັບຊັ້ນ, ໜ້າຕາ, ຄວາມອ້ອມຄ້ອມ ແລະ ຄວາມກົມກຽວຂອງກຸ່ມ. ບາງເຕັກນິກຂອງລາວ ໃນການອ່ອນຄຳຕິຕຽນ ຈະຮູ້ສຶກຄຸ້ນເຄີຍ ແລະ ເຂົ້າກັນໄດ້ດີກັບຮູບແບບການສື່ສານລາວ ທີ່ມັກນິຍົມຄວາມອ້ອມຄ້ອມ ແລະ ການຮັກສາໜ້າຢູ່ແລ້ວ; ອັນອື່ນໆ — ເຊັ່ນ ຄຳຊົມແບບເປີດເຜີຍ ຫຼື ການເອີ້ນຊື່ຕົ້ນແບບບໍ່ເປັນທາງການແບບອາເມຣິກາ — ອາດຕ້ອງການການປັບໃຫ້ເໝາະສົມແທ້ໆ ບໍ່ແມ່ນເອົາມາໃຊ້ໂດຍກົງ.$$)
  )),
    jsonb_build_object('type', $$p$$, 'text', $$ຖ້າຖືເອົາຂໍ້ລະມັດລະວັງເຫຼົ່ານັ້ນໄວ້ ຄຸນປະໂຫຍດແທ້ຈິງຂອງປຶ້ມນີ້ຍັງຄົງຢູ່: ຂໍ້ໂຕ້ແຍ້ງທີ່ຈັດລຽງດີ ແລະ ສອດຄ່ອງ ວ່າ ຄວາມເຄົາລົບ, ຄຳຊົມທີ່ຈິງໃຈ ແລະ ຄວາມສົນໃຈຕໍ່ມຸມມອງຂອງອີກຝ່າຍ ໃຫ້ຜົນດີກວ່າການຕິຕຽນ, ການໂຕ້ຖຽງ ແລະ ການບີບບັງຄັບ ຫຼາຍກວ່າທີ່ຄົນສ່ວນຫຼາຍຄິດໂດຍທຳມະຊາດ. ອ່ານມັນເປັນຊຸດຫຼັກການທີ່ຜ່ານການທົດສອບດ້ວຍປະສົບການ ເພື່ອຊັ່ງນ້ຳໜັກກັບການຕັດສິນໃຈ ແລະ ບໍລິບົດຂອງທ່ານເອງ ບໍ່ແມ່ນຄູ່ມືທາງວິທະຍາສາດ ຫຼື ທາງລັດທາງສິນທຳ.$$)
  ))
  ),
  glossary_en = jsonb_build_array(
    jsonb_build_object('term', $$The fundamental technique$$, 'body', $$Seeking to understand why someone acted as they did, instead of condemning them — Carnegie's foundational alternative to criticism.$$),
    jsonb_build_object('term', $$Honest appreciation$$, 'body', $$Specific, sincere, deserved recognition of another person's qualities or actions, given without an ulterior motive — distinct from flattery.$$),
    jsonb_build_object('term', $$Eager want$$, 'body', $$A desire the other person already has, or can be shown a genuine stake in, that your request happens to satisfy.$$),
    jsonb_build_object('term', $$The Socratic method$$, 'body', $$Opening a conversation by securing agreement on small points before approaching the point of disagreement, so the other person stays psychologically inclined to keep agreeing.$$),
    jsonb_build_object('term', $$Saving face$$, 'body', $$Preserving another person's dignity, especially when correcting them or when they are clearly in the wrong, rather than exposing or humiliating them.$$),
    jsonb_build_object('term', $$Arousing an eager want$$, 'body', $$Framing a request or idea in terms of what the other person already values, rather than in terms of what you personally need from them.$$),
    jsonb_build_object('term', $$Nobler motives$$, 'body', $$The better version of a person's self-image — fair, honest, generous — that a well-framed appeal can draw forward more reliably than a threat or demand.$$)
  ),
  glossary_lo = jsonb_build_array(
    jsonb_build_object('term', $$ເຕັກນິກພື້ນຖານ$$, 'body', $$ການພະຍາຍາມເຂົ້າໃຈວ່າເປັນຫຍັງຄົນຈຶ່ງເຮັດແບບນັ້ນ ແທນທີ່ຈະກ່າວໂທດເຂົາ — ທາງເລືອກພື້ນຖານຂອງ Carnegie ແທນການຕິຕຽນ.$$),
    jsonb_build_object('term', $$ຄຳຊົມທີ່ຈິງໃຈ (Honest appreciation)$$, 'body', $$ການຍອມຮັບຄຸນສົມບັດ ຫຼື ການກະທຳຂອງຄົນອື່ນ ຢ່າງສະເພາະ, ຈິງໃຈ ແລະ ຄູ່ຄວນ ໃຫ້ໂດຍບໍ່ມີແຮງຈູງໃຈແອບແຝງ — ແຕກຕ່າງຈາກຄຳປໍ້ຍໍ.$$),
    jsonb_build_object('term', $$ຄວາມຢາກຢ່າງແຮງກ້າ (Eager want)$$, 'body', $$ຄວາມປາຖະໜາທີ່ອີກຝ່າຍມີຢູ່ແລ້ວ ຫຼືສາມາດສະແດງໃຫ້ເຫັນວ່າມີສ່ວນກ່ຽວຂ້ອງ ຊຶ່ງຄຳຮ້ອງຂໍຂອງທ່ານພໍດີຕອບສະໜອງ.$$),
    jsonb_build_object('term', $$ວິທີ Socratic (The Socratic method)$$, 'body', $$ການເປີດການສົນທະນາດ້ວຍການໄດ້ຮັບຄວາມເຫັນດີໃນຈຸດນ້ອຍໆກ່ອນ ຈາກນັ້ນຈຶ່ງເຂົ້າຫາຈຸດຂັດແຍ້ງ ເພື່ອໃຫ້ອີກຝ່າຍຄົງແນວໂນ້ມທາງຈິດໃຈທີ່ຈະສືບຕໍ່ເຫັນດີ.$$),
    jsonb_build_object('term', $$ການຮັກສາໜ້າ (Saving face)$$, 'body', $$ການຮັກສາກຽດຂອງອີກຝ່າຍໄວ້ ໂດຍສະເພາະຕອນແກ້ໄຂເຂົາ ຫຼື ຕອນເຂົາຜິດຢ່າງຊັດເຈນ ແທນທີ່ຈະເປີດເຜີຍ ຫຼື ເຮັດໃຫ້ເຂົາອັບອາຍ.$$),
    jsonb_build_object('term', $$ການປຸກຄວາມຢາກຢ່າງແຮງກ້າ (Arousing an eager want)$$, 'body', $$ການວາງກອບຄຳຮ້ອງຂໍ ຫຼື ແນວຄິດ ໃນແງ່ຂອງສິ່ງທີ່ອີກຝ່າຍໃຫ້ຄຸນຄ່າຢູ່ແລ້ວ ແທນທີ່ຈະເປັນສິ່ງທີ່ທ່ານຕ້ອງການຈາກເຂົາ.$$),
    jsonb_build_object('term', $$ແຮງຈູງໃຈອັນສູງສົ່ງ (Nobler motives)$$, 'body', $$ພາບຕົນເອງແບບທີ່ດີກວ່າຂອງຄົນ — ຍຸຕິທຳ, ຊື່ສັດ, ໃຈກວ້າງ — ຊຶ່ງຄຳຮ້ອງຂໍທີ່ວາງກອບດີ ສາມາດດຶງອອກມາໄດ້ໜ້າເຊື່ອຖືກວ່າການຂົ່ມຂູ່ ຫຼື ຄຳສັ່ງ.$$)
  ),
  reflection_questions_en = array[$$Think of a recent disagreement you "won." What did winning it actually cost you in the other person's goodwill, and was it worth the trade?$$, $$Carnegie insists these techniques only work long-term if the interest in people is genuine. Where is the line, in your own practice, between sincere appreciation and performing appreciation to get something?$$, $$Several principles — never say "you're wrong," avoid arguments — counsel against direct confrontation. When does a situation actually call for blunt disagreement rather than diplomacy, and how would you tell the difference in the moment?$$, $$The book was written from a specific mid-century American business context. Which of its techniques translate comfortably into Lao or regional norms around hierarchy, face, and directness, and which would need real adaptation?$$, $$Pick one principle from Part Four (leadership without resentment). How would you apply it the next time you need to correct someone, and what would sincerity actually require of you in that moment, beyond just following the script?$$],
  reflection_questions_lo = array[$$ຄິດເຖິງຄວາມຂັດແຍ້ງທີ່ທ່ານເຄີຍ "ຊະນະ" ຫາກໍ່ນີ້. ການຊະນະນັ້ນເສຍຄ່າຫຍັງແທ້ໆຕໍ່ຄວາມປາຖະໜາດີຂອງອີກຝ່າຍ ແລະ ມັນຄຸ້ມຄ່າກັບການແລກປ່ຽນນັ້ນບໍ?$$, $$Carnegie ຢ້ຳວ່າ ເຕັກນິກເຫຼົ່ານີ້ຈະໄດ້ຜົນໃນໄລຍະຍາວ ກໍ່ຕໍ່ເມື່ອຄວາມສົນໃຈຕໍ່ຄົນເປັນຄວາມຈິງໃຈ. ໃນການປະຕິບັດຂອງທ່ານເອງ ເສັ້ນແບ່ງຢູ່ໃສ ລະຫວ່າງຄຳຊົມທີ່ຈິງໃຈ ກັບການສະແດງຄຳຊົມເພື່ອໃຫ້ໄດ້ບາງສິ່ງບາງຢ່າງ?$$, $$ຫຼາຍຫຼັກການ — ຢ່າບອກວ່າ "ທ່ານຜິດ", ຫຼີກລ່ຽງການໂຕ້ຖຽງ — ແນະນຳໃຫ້ຫຼີກລ່ຽງການປະທະໂດຍກົງ. ສະຖານະການແບບໃດແທ້ໆ ທີ່ຕ້ອງການຄວາມເຫັນຕ່າງແບບກົງໄປກົງມາ ແທນທີ່ຈະເປັນການທູດ ແລະ ທ່ານຈະແຍກຄວາມແຕກຕ່າງນັ້ນອອກແນວໃດໃນຂະນະນັ້ນ?$$, $$ປຶ້ມນີ້ຖືກຂຽນຈາກບໍລິບົດທຸລະກິດອາເມຣິກາກາງສະຕະວັດສະເພາະ. ເຕັກນິກໃດຂອງມັນ ແປເປັນມາດຕະຖານລາວ ຫຼື ພາກພື້ນ ກ່ຽວກັບລຳດັບຊັ້ນ, ໜ້າຕາ ແລະ ຄວາມກົງໄປກົງມາ ໄດ້ຢ່າງສະບາຍໆ ແລະ ອັນໃດຕ້ອງການການປັບຕົວແທ້ໆ?$$, $$ເລືອກຫຼັກການໜຶ່ງຈາກພາກທີ 4 (ການເປັນຜູ້ນຳໂດຍບໍ່ກໍ່ໃຫ້ເກີດຄວາມຄຽດແຄ້ນ). ທ່ານຈະນຳໃຊ້ມັນແນວໃດ ໃນຄັ້ງຕໍ່ໄປທີ່ທ່ານຕ້ອງແກ້ໄຂຄົນໃດຄົນໜຶ່ງ ແລະ ຄວາມຈິງໃຈຕ້ອງການຫຍັງແທ້ໆຈາກທ່ານໃນຂະນະນັ້ນ ນອກເໜືອຈາກການເຮັດຕາມສະຄຣິບ?$$],
  key_takeaways_en = array[$$Criticism rarely changes behavior — it mostly triggers defensiveness and resentment, so it should be a last resort, not a first move.$$, $$Genuine, specific appreciation is one of the cheapest and most powerful tools available; flattery is its insincere, self-defeating cousin.$$, $$People respond to what they want, not to your reasons for wanting it — find the real overlap before you ask for anything.$$, $$Becoming genuinely interested in others, smiling, and remembering names cost nothing and build goodwill faster than being interesting yourself.$$, $$Listening attentively and making someone feel sincerely important wins more loyalty than clever conversation.$$, $$You cannot really win an argument — even a technical win usually costs more in resentment than it gains in agreement.$$, $$People change their minds through their own reasoning and words far more readily than through yours — let them talk, and let the idea feel like theirs.$$, $$Appealing to someone's better self and making an idea vivid moves people further than flat facts or direct demands.$$, $$Corrections land far better wrapped in genuine praise, indirect signals, and questions than delivered as blunt judgment.$$, $$Lasting influence requires real sincerity underneath every technique — without it, the same methods curdle into manipulation.$$],
  key_takeaways_lo = array[$$ການຕິຕຽນບໍ່ຄ່ອຍປ່ຽນພຶດຕິກຳ — ສ່ວນຫຼາຍມັນກະຕຸ້ນຄວາມຮູ້ສຶກປ້ອງກັນຕົນເອງ ແລະ ຄວາມຄຽດແຄ້ນ ດັ່ງນັ້ນມັນຄວນເປັນທາງເລືອກສຸດທ້າຍ ບໍ່ແມ່ນອັນທຳອິດ.$$, $$ຄຳຊົມທີ່ຈິງໃຈ ແລະ ສະເພາະ ຄືເຄື່ອງມືທີ່ຖືກທີ່ສຸດ ແລະ ມີພະລັງທີ່ສຸດອັນໜຶ່ງ; ຄຳປໍ້ຍໍ ຄືພີ່ນ້ອງທີ່ບໍ່ຈິງໃຈ ແລະ ທຳລາຍຕົນເອງຂອງມັນ.$$, $$ຄົນຕອບສະໜອງຕໍ່ສິ່ງທີ່ເຂົາຢາກໄດ້ ບໍ່ແມ່ນເຫດຜົນຂອງທ່ານ — ໃຫ້ຫາຈຸດທັບຊ້ອນທີ່ແທ້ຈິງກ່ອນຮ້ອງຂໍຫຍັງ.$$, $$ການສົນໃຈຄົນອື່ນຢ່າງແທ້ຈິງ, ການຍິ້ມ ແລະ ການຈື່ຊື່ ບໍ່ໄດ້ໃຊ້ຫຍັງເລີຍ ແຕ່ສ້າງຄວາມປາຖະໜາດີໄວກວ່າການພະຍາຍາມເປັນຄົນໜ້າສົນໃຈເອງ.$$, $$ການຮັບຟັງຢ່າງຕັ້ງໃຈ ແລະ ການເຮັດໃຫ້ຄົນຮູ້ສຶກສຳຄັນຢ່າງຈິງໃຈ ໄດ້ຄວາມສັດຊື່ຫຼາຍກວ່າການສົນທະນາທີ່ສະຫຼາດ.$$, $$ທ່ານຊະນະການໂຕ້ຖຽງແທ້ໆບໍ່ໄດ້ — ແມ່ນແຕ່ຊະນະໃນທາງເຕັກນິກ ມັກເສຍຫຼາຍໃນຄວາມຄຽດແຄ້ນ ຫຼາຍກວ່າໄດ້ໃນຄວາມເຫັນດີ.$$, $$ຄົນປ່ຽນຄວາມຄິດຜ່ານເຫດຜົນ ແລະ ຄຳເວົ້າຂອງຕົນເອງ ໄດ້ງ່າຍກວ່າຂອງທ່ານຫຼາຍ — ໃຫ້ເຂົາເວົ້າ ແລະ ໃຫ້ແນວຄິດຮູ້ສຶກເປັນຂອງເຂົາເອງ.$$, $$ການດຶງດູດຕົວຕົນທີ່ດີກວ່າຂອງຄົນ ແລະ ການເຮັດໃຫ້ແນວຄິດເຫັນເປັນຮູບປະທຳ ຍ້າຍໃຈຄົນໄດ້ຫຼາຍກວ່າຂໍ້ເທັດຈິງຮາບພຽງ ຫຼື ຄຳຮ້ອງຂໍໂດຍກົງ.$$, $$ການແກ້ໄຂ ຈະໄດ້ຮັບການຕອບຮັບດີກວ່າຫຼາຍ ຖ້າຫໍ່ຫຸ້ມດ້ວຍຄຳຊົມທີ່ຈິງໃຈ, ສັນຍານທາງອ້ອມ ແລະ ຄຳຖາມ ແທນທີ່ຈະສົ່ງເປັນການຕັດສິນແບບຮາບພຽງ.$$, $$ອິດທິພົນທີ່ຄົງທົນ ຕ້ອງການຄວາມຈິງໃຈແທ້ຢູ່ເບື້ອງຫຼັງທຸກເຕັກນິກ — ຖ້າບໍ່ມີມັນ ວິທີການດຽວກັນ ຈະກາຍເປັນການຫຼອກລວງ.$$]
where book_id = '58b835a1-9b0b-4fab-b304-bd2eb818888a';

-- Eat That Frog! — Brian Tracy
update public.premium_lessons set
  status = 'PUBLISHED', published_at = coalesce(published_at, now()), estimated_minutes = 15,
  summary_en = $$Twenty-one practical ways to stop procrastinating and get more of what matters done.$$,
  summary_lo = $$21 ວິທີປະຕິບັດເພື່ອເລີກຜັດວັນ ແລະ ເຮັດວຽກທີ່ສຳຄັນໃຫ້ສຳເລັດຫຼາຍຂຶ້ນ.$$,
  deck_en = $$Brian Tracy's premise is almost insultingly simple: every day carries at least one big, ugly task you are tempted to avoid, and your entire productivity for that day hinges on whether you do it first or let it stalk you until 4pm. Eat That Frog! is not a theory of motivation — it is a toolbox of twenty-one blunt, specific tactics for deciding what the frog actually is and then eating it before anything else gets in the way. This lesson groups those twenty-one tactics into their natural clusters — prioritization methods, planning habits, focus discipline, and self-development — and closes with a clear-eyed look at where a book this confident and this short inevitably cuts corners.$$,
  deck_lo = $$ແນວຄິດຫຼັກຂອງ Brian Tracy ຟັງງ່າຍຈົນເກືອບຄືກັບເລື່ອງກຳປັ້ນທຸບດິນ: ທຸກມື້ມີວຽກໃຫຍ່ ໜ້າຢ້ານ ຢ່າງໜ້ອຍໜຶ່ງອັນ ທີ່ທ່ານຢາກຫຼີກລ່ຽງ ແລະ ຜົນຜະລິດຂອງທ່ານໃນມື້ນັ້ນທັງໝົດ ຂຶ້ນຢູ່ກັບວ່າທ່ານເຮັດມັນກ່ອນ ຫຼື ປ່ອຍໃຫ້ມັນຕິດຕາມທ່ານໄປຈົນເຖິງ 4 ໂມງແລງ. Eat That Frog! ບໍ່ແມ່ນທິດສະດີແຮງຈູງໃຈ — ແຕ່ເປັນກ່ອງເຄື່ອງມືທີ່ມີ 21 ກົນລະຍຸດ ຊັດເຈນ ແລະ ກົງໄປກົງມາ ສຳລັບຕັດສິນວ່າ "ກົບ" ຂອງທ່ານແທ້ໆແມ່ນຫຍັງ ແລ້ວກິນມັນກ່ອນທີ່ຫຍັງອື່ນຈະມາຂວາງທາງ. ບົດຮຽນນີ້ຈັດກຸ່ມ 21 ກົນລະຍຸດເຫຼົ່ານັ້ນຕາມໝວດທຳມະຊາດຂອງມັນ — ວິທີຈັດລຳດັບຄວາມສຳຄັນ, ນິໄສການວາງແຜນ, ວິໄນການຈົດຈໍ່ ແລະ ການພັດທະນາຕົນເອງ — ແລະ ປິດທ້າຍດ້ວຍການວິເຄາະຢ່າງກົງໄປກົງມາ ວ່າປຶ້ມທີ່ໝັ້ນໃຈ ແລະ ສັ້ນຂະໜາດນີ້ ຫຼີກລ່ຽງບໍ່ໄດ້ທີ່ຈະຕັດອອກຈຸດໃດແດ່.$$,
  content_en = jsonb_build_array(
    jsonb_build_object('heading', $$The frog: what procrastination actually costs$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy borrows a line often attributed to Mark Twain: if the first thing you do each morning is eat a live frog, nothing worse will happen to you the rest of the day. The frog is your biggest, most important task — the one most likely to have a large impact on your results, and also the one you are most tempted to put off. His argument is that this single habit, more than any other, separates people who accomplish a great deal from people who stay busy without getting much done.$$),
    jsonb_build_object('type', $$term$$, 'term', $$The frog$$, 'body', $$Your single biggest, most important task at any given time — usually identifiable as the one you are most likely to procrastinate on, because it is the one that matters most.$$),
    jsonb_build_object('type', $$p$$, 'text', $$The book's second rule of frog-eating follows from the first: if you have two frogs, eat the ugliest one first. People naturally drift toward the easier or more pleasant of two important tasks, which quietly guarantees the harder, higher-value one gets pushed to tomorrow — and tomorrow has its own new frog competing for the same slot. Tracy's claim is that this pattern, repeated daily, is the actual mechanism by which years pass without important goals ever being reached, even though the person involved was busy the entire time.$$)
  ), 'oneline', $$Eat the biggest, ugliest task first thing in the morning, before anything else gets a vote.$$),
    jsonb_build_object('heading', $$The 80/20 rule and the ABCDE method$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy leans heavily on the Pareto Principle, the observation that roughly 20% of your activities will account for roughly 80% of your results. Applied to a daily task list, this means most of the items on it are close to irrelevant to your actual success, while a small handful are doing almost all the work. The practical danger is that low-value tasks are usually easier and faster to finish, so a person can spend an entire day clearing a long list, feel productive by the count of items checked off, and still have avoided the two or three tasks that actually mattered.$$),
    jsonb_build_object('type', $$term$$, 'term', $$ABCDE method$$, 'body', $$A system for ranking every item on a task list by consequence rather than urgency, before starting work: A tasks carry serious consequences if not done, B tasks carry mild consequences, C tasks carry no consequences at all, D tasks should be delegated, and E tasks should be eliminated.$$),
    jsonb_build_object('type', $$list$$, 'items', jsonb_build_array(
    jsonb_build_object('label', $$A tasks$$, 'body', $$Serious positive or negative consequences attach to doing or not doing them. If you have more than one A task, they get ranked A-1, A-2, A-3 by importance, and A-1 is the frog.$$),
    jsonb_build_object('label', $$B tasks$$, 'body', $$Mildly unpleasant consequences follow if skipped — a task worth doing, but never at the expense of an A task.$$),
    jsonb_build_object('label', $$C tasks$$, 'body', $$No consequences either way. Tracy's example is a coffee catch-up with a coworker: pleasant, but irrelevant to results.$$),
    jsonb_build_object('label', $$D tasks$$, 'body', $$Worth doing, but not by you — delegate them to free up time for A tasks.$$),
    jsonb_build_object('label', $$E tasks$$, 'body', $$Eliminate entirely. Often habitual activities that survive purely because no one has questioned whether they still need to happen.$$)
  )),
    jsonb_build_object('type', $$p$$, 'text', $$The rule that makes the method work, and the one people break most often, is simple: never touch a B task while an A task sits undone. Tracy's observation is that B tasks are frequently more comfortable to do — they are exactly the trap that lets a genuinely important A task quietly slide to tomorrow while a person still feels productive.$$)
  ), 'oneline', $$Rank tasks by consequence, not urgency, and refuse to touch a B task until every A task is finished.$$),
    jsonb_build_object('heading', $$Consequences are the real measure of priority$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy proposes a single test for deciding what actually deserves your attention: what are the likely consequences of doing or not doing this task? Tasks with serious, long-term consequences are important, almost regardless of how urgent or pleasant they feel in the moment; tasks with little or no consequence are not important, no matter how urgently they seem to demand a response.$$),
    jsonb_build_object('type', $$p$$, 'text', $$This directly targets a specific failure mode: mistaking urgency for importance. Ringing phones, incoming messages, and other people's requests all generate a feeling of urgency that has nothing to do with their actual consequence, and Tracy argues most people default to responding to whatever feels loudest rather than whatever matters most. A report due in three months with major consequences for your career is, by this test, more important than an email that feels like it needs a reply in the next ten minutes but changes nothing either way.$$),
    jsonb_build_object('type', $$term$$, 'term', $$Key result areas$$, 'body', $$The handful of specific outcomes — usually five to seven — that most determine whether you are succeeding in your job or role. Tracy argues that being excellent in your key result areas matters more than almost anything else you could optimize.$$),
    jsonb_build_object('type', $$p$$, 'text', $$Tracy pairs the consequences test with the idea of key result areas: before you can judge which tasks carry the biggest consequences, you need clarity on what your job or goal is actually for. He recommends periodically listing the outcomes that most define success in your role and rating yourself honestly on each one — because the weakest key result area, not the strongest, tends to set the ceiling on your overall performance.$$)
  ), 'oneline', $$Judge a task by its long-term consequences, not by how loudly or urgently it demands attention right now.$$),
    jsonb_build_object('heading', $$The law of three$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy narrows the focus further with what he calls the law of three: for most people in most jobs, three tasks account for 90% or more of the value they contribute. His suggested exercise is blunt — if you could only do one thing all day, what would it be; if you could do a second, what would that be; and a third. The exercise is designed to strip away the noise of a long task list and surface what genuinely matters.$$),
    jsonb_build_object('type', $$p$$, 'text', $$The practical use of the law of three is less about permanently narrowing your job to three tasks and more about a recurring gut-check: whenever the day feels scattered, this exercise re-identifies the small set of activities actually worth protecting, and everything else can be evaluated against whether it serves one of those three.$$)
  ), 'oneline', $$Most of your real contribution comes from a short list of about three tasks — find them and protect them.$$),
    jsonb_build_object('heading', $$Plan every day, week, and month in advance$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy treats planning itself as a high-leverage activity, not administrative overhead: every minute spent planning, he argues, saves multiple minutes in execution, because a written plan removes the friction of deciding what to do next in the moment — a decision that, repeated dozens of times a day, is itself a major source of lost time.$$),
    jsonb_build_object('type', $$list$$, 'items', jsonb_build_array(
    jsonb_build_object('label', $$Plan the night before.$$, 'body', $$Write tomorrow's task list at the end of today, so your subconscious mind works on the list overnight and you start the morning already knowing your frog rather than spending the first hour figuring it out.$$),
    jsonb_build_object('label', $$Work from a list, always.$$, 'body', $$Add new tasks to the list as they come up rather than acting on them immediately, and cross items off as completed. A list keeps the whole set of commitments visible at once, which is what makes real prioritization possible.$$),
    jsonb_build_object('label', $$Plan in layers.$$, 'body', $$Monthly and weekly plans set the frame; the daily list is where those larger plans actually get executed one task at a time. Skipping the higher layers tends to produce a daily list full of busywork with no clear connection to larger goals.$$)
  ))
  ), 'oneline', $$A plan written in advance turns a hundred small decisions into one decision, made calmly, before the day gets noisy.$$),
    jsonb_build_object('heading', $$Creative procrastination: choosing what NOT to do$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy's twist on procrastination is that it is unavoidable — no one has time for everything — so the only real choice is which tasks to procrastinate on. Most people procrastinate by accident, deferring whatever feels least urgent or most uncomfortable in the moment, which reliably means the low-value tasks get done and the high-value ones slide.$$),
    jsonb_build_object('type', $$term$$, 'term', $$Creative procrastination$$, 'body', $$Deliberately and consciously choosing to delay, delegate, or drop the low-value tasks on your list, on purpose, so that your time and energy go toward the few tasks that carry real consequences.$$),
    jsonb_build_object('type', $$p$$, 'text', $$The reframe matters because it turns procrastination from something to feel guilty about into a tool to use on purpose. Since you cannot do everything anyway, the only meaningful question is whether the tasks you are neglecting are the C, D, and E tasks — which is fine — or the A tasks, which is the actual problem.$$)
  ), 'oneline', $$You cannot avoid procrastinating on something — the only real choice is deciding what that something is.$$),
    jsonb_build_object('heading', $$Single-handling: start it, stay with it, finish it$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy's closing mechanical principle addresses how a task gets done once it has been chosen: single-handling, or working on one task, continuously, without switching away, until it is 100% complete. He argues that switching between tasks carries a hidden cost far larger than most people assume — every restart requires re-establishing focus and momentum, so a task interrupted repeatedly can take several times longer than the same task worked straight through.$$),
    jsonb_build_object('type', $$term$$, 'term', $$Single-handling$$, 'body', $$Selecting the most important task, starting on it, and staying with it single-mindedly until it is completely finished, before allowing yourself to move to anything else.$$),
    jsonb_build_object('type', $$p$$, 'text', $$This is where Tracy's advice becomes most demanding in practice: it means resisting email, messages, and other people's minor requests for the duration of the task, not just resisting the urge to switch to something more enjoyable. His claim is that the discipline of finishing one thing completely, rather than making partial progress on several things, is one of the most reliable productivity habits a person can build — and one of the easiest to talk yourself out of in the moment.$$)
  ), 'oneline', $$Task-switching is expensive in ways that are easy to underestimate — pick one task and finish it before starting the next.$$),
    jsonb_build_object('heading', $$Upgrade your key skills$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy treats skill level as a multiplier on everything else in this system: prioritizing perfectly still leaves you slow if you are weak at the task itself, while genuine competence in your key result areas makes the same amount of time produce far more. His specific claim is that a skill deficiency in even one critical area can act as a bottleneck on your entire output, regardless of how well you manage the rest of your time.$$),
    jsonb_build_object('type', $$p$$, 'text', $$The practical instruction is to identify the one skill that, if you developed it to excellence, would have the single greatest positive impact on your results, and then to treat becoming excellent at it as an ongoing priority — not a one-time course, but continuous, deliberate improvement, since the value of a skill compounds the longer you hold it.$$)
  ), 'oneline', $$A weak skill in a critical area quietly caps your output no matter how well you manage everything else.$$),
    jsonb_build_object('heading', $$Find your key constraint$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy adapts a version of the theory of constraints to personal productivity: in any goal or process, there is a single limiting factor — a bottleneck — that determines the speed of the entire chain, and improving anything other than that bottleneck does not meaningfully speed up the result.$$),
    jsonb_build_object('type', $$term$$, 'term', $$Key constraint$$, 'body', $$The single factor, internal or external, that most limits how fast you are moving toward an important goal. Working on anything other than the constraint produces little or no improvement in overall speed.$$),
    jsonb_build_object('type', $$p$$, 'text', $$His practical instruction is to ask, honestly, what factor is setting the pace on your most important goal right now — and to be willing to accept that it is often something internal, a skill you lack or a habit you have not built, rather than an external circumstance. Identifying the real constraint, he argues, is usually more valuable than working harder on everything else combined, because effort spent anywhere except the actual bottleneck does not move the goal any faster.$$)
  ), 'oneline', $$Every goal has one true bottleneck — find it, because effort spent anywhere else barely moves the needle.$$),
    jsonb_build_object('heading', $$How to read this book$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Eat That Frog! is written as a short, punchy field manual meant to be read quickly and acted on immediately, and that format is both the source of its usefulness and the source of its real limits.$$),
    jsonb_build_object('type', $$list$$, 'items', jsonb_build_array(
    jsonb_build_object('label', $$It assumes a fair amount of autonomy over your own schedule.$$, 'body', $$Many of the tactics — plan the night before, single-handle a task for hours, refuse to touch a B task — work best for someone with real control over their calendar, like a manager, founder, or knowledge worker. Shift work, customer-facing jobs, and roles with constant externally imposed interruptions offer much less room to apply the advice as written.$$),
    jsonb_build_object('label', $$Eating the frog first assumes your energy peaks in the morning.$$, 'body', $$Tracy writes as if mornings are universally the best time for hard work, but focus and energy genuinely vary by person and by chronotype. The underlying principle — do your most consequential task before lower-value ones can crowd it out — holds regardless of the hour; the specific "morning" framing does not apply to everyone equally.$$),
    jsonb_build_object('label', $$Some tasks cannot simply be started on your own timeline.$$, 'body', $$Single-handling and eating the frog first both assume you control when a task begins. In practice, many important tasks depend on someone else's input, approval, or availability, and no amount of personal discipline moves those dependencies faster.$$),
    jsonb_build_object('label', $$The book is far stronger on technique than on why people procrastinate.$$, 'body', $$Tracy treats procrastination mainly as a scheduling and prioritization problem. For a large share of procrastinators, the real driver is emotional — fear of failure, perfectionism, unclear or conflicting goals, or simple aversion to an unpleasant task — and a ranking method alone does not resolve those underlying causes. Readers who recognize this pattern in themselves may need tools beyond ABCDE and single-handling.$$),
    jsonb_build_object('label', $$The 21 ways overlap considerably.$$, 'body', $$Several of the original twenty-one tactics restate the same underlying idea — prioritize by consequence, protect focus, plan ahead — in slightly different packaging. The book reads better as a menu to sample from than as twenty-one genuinely distinct techniques to master in sequence.$$)
  )),
    jsonb_build_object('type', $$p$$, 'text', $$Taken with those caveats, the book's real contribution holds up: a short, concrete set of habits — rank by consequence, protect your A-1 task, plan in advance, finish what you start — that most people can put into practice the same day they read it, even if it is not a complete account of why procrastination happens in the first place.$$)
  ))
  ),
  content_lo = jsonb_build_array(
    jsonb_build_object('heading', $$ກົບ: ຕົ້ນທຶນທີ່ແທ້ຈິງຂອງການຜັດວັນ$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy ຢືມປະໂຫຍກທີ່ມັກຖືກອ້າງອີງວ່າເປັນຂອງ Mark Twain: ຖ້າສິ່ງທຳອິດທີ່ທ່ານເຮັດທຸກເຊົ້າ ຄືການກິນກົບທີ່ຍັງມີຊີວິດ ບໍ່ມີຫຍັງທີ່ຮ້າຍແຮງກວ່ານັ້ນຈະເກີດຂຶ້ນກັບທ່ານອີກຕະຫຼອດມື້. ກົບຄືວຽກທີ່ໃຫຍ່ ແລະ ສຳຄັນທີ່ສຸດຂອງທ່ານ — ວຽກທີ່ມີໂອກາດສົ່ງຜົນກະທົບໃຫຍ່ຫຼວງທີ່ສຸດຕໍ່ຜົນລັບຂອງທ່ານ ແລະ ກໍ່ເປັນວຽກທີ່ທ່ານຢາກຜັດອອກໄປຫຼາຍທີ່ສຸດພ້ອມກັນ. ຂໍ້ໂຕ້ແຍ້ງຂອງລາວຄື ນິໄສອັນດຽວນີ້ ຫຼາຍກວ່າອັນອື່ນໃດ ຄືສິ່ງທີ່ແຍກຄົນທີ່ເຮັດສຳເລັດຫຼາຍ ອອກຈາກຄົນທີ່ຫຍຸ້ງຢູ່ຕະຫຼອດແຕ່ບໍ່ໄດ້ຫຍັງຫຼາຍ.$$),
    jsonb_build_object('type', $$term$$, 'term', $$ກົບ (The frog)$$, 'body', $$ວຽກທີ່ໃຫຍ່ ແລະ ສຳຄັນທີ່ສຸດຂອງທ່ານໃນຊ່ວງເວລາໃດໜຶ່ງ — ປົກກະຕິສັງເກດໄດ້ວ່າ ຄືວຽກທີ່ທ່ານມັກຜັດວັນທີ່ສຸດ ເພາະມັນເປັນວຽກທີ່ສຳຄັນທີ່ສຸດພໍດີ.$$),
    jsonb_build_object('type', $$p$$, 'text', $$ກົດຂໍ້ທີສອງຂອງການກິນກົບ ຕາມມາຈາກຂໍ້ທຳອິດ: ຖ້າທ່ານມີກົບສອງໂຕ ໃຫ້ກິນໂຕທີ່ໜ້າກຽດຊັງທີ່ສຸດກ່ອນ. ຄົນເຮົາມີແນວໂນ້ມທຳມະຊາດ ຫັນໄປຫາວຽກທີ່ງ່າຍກວ່າ ຫຼື ໜ້າພໍໃຈກວ່າ ໃນສອງວຽກສຳຄັນ ຊຶ່ງຮັບປະກັນຢ່າງງຽບໆວ່າວຽກທີ່ຍາກ ແລະ ມີຄຸນຄ່າສູງກວ່າ ຈະຖືກຍູ້ໄປມື້ອື່ນ — ແລະ ມື້ອື່ນກໍ່ຈະມີກົບໃໝ່ຂອງມັນເອງ ມາແກ່ງແຍ່ງບ່ອນດຽວກັນ. ຂໍ້ອ້າງຂອງ Tracy ຄື ຮູບແບບນີ້ ຖ້າເກີດຂຶ້ນຊ້ຳທຸກມື້ ຄືກົນໄກແທ້ຈິງທີ່ເຮັດໃຫ້ຫຼາຍປີຜ່ານໄປ ໂດຍທີ່ເປົ້າໝາຍສຳຄັນບໍ່ເຄີຍບັນລຸໄດ້ ທັງໆທີ່ຄົນຄົນນັ້ນຫຍຸ້ງຢູ່ຕະຫຼອດເວລາ.$$)
  ), 'oneline', $$ກິນວຽກທີ່ໃຫຍ່ ແລະ ໜ້າກຽດຊັງທີ່ສຸດ ຕັ້ງແຕ່ຕອນເຊົ້າ ກ່ອນສິ່ງອື່ນໃດຈະມີສິດອອກສຽງ.$$),
    jsonb_build_object('heading', $$ກົດ 80/20 ແລະ ວິທີ ABCDE$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$Tracy ອີງໃສ່ຫຼັກການ Pareto ຢ່າງໜັກ ຊຶ່ງເປັນຂໍ້ສັງເກດວ່າ ປະມານ 20% ຂອງກິດຈະກຳຂອງທ່ານ ຈະສ້າງຜົນລັບໄດ້ປະມານ 80%. ເມື່ອນຳໄປໃຊ້ກັບລາຍການວຽກປະຈຳວັນ ໝາຍຄວາມວ່າ ວຽກສ່ວນຫຼາຍໃນລາຍການ ແທ້ຈິງແລ້ວແທບບໍ່ມີຄວາມສຳຄັນ ໃນຂະນະທີ່ວຽກຈຳນວນນ້ອຍໆ ເປັນຜູ້ສ້າງຜົນເກືອບທັງໝົດ. ອັນຕະລາຍໃນທາງປະຕິບັດ ຄື ວຽກທີ່ມີຄຸນຄ່າຕ່ຳ ມັກງ່າຍ ແລະ ໄວກວ່າໃນການເຮັດໃຫ້ສຳເລັດ ດັ່ງນັ້ນຄົນເຮົາອາດໃຊ້ເວລາທັງມື້ ລ້າງລາຍການອັນຍາວ ຮູ້ສຶກມີຜົນຜະລິດຈາກຈຳນວນລາຍການທີ່ຂີດອອກ ແຕ່ຍັງຫຼີກລ່ຽງສອງ ຫຼື ສາມວຽກທີ່ສຳຄັນແທ້ໆຢູ່ດີ.$$),
    jsonb_build_object('type', $$term$$, 'term', $$ວິທີ ABCDE$$, 'body', $$ລະບົບຈັດອັນດັບທຸກລາຍການໃນລາຍການວຽກ ຕາມຜົນສະທ້ອນ ບໍ່ແມ່ນຄວາມຮີບດ່ວນ ກ່ອນເລີ່ມລົງມືເຮັດ: ວຽກ A ມີຜົນສະທ້ອນຮ້າຍແຮງຫາກບໍ່ເຮັດ, ວຽກ B ມີຜົນສະທ້ອນເລັກນ້ອຍ, ວຽກ C ບໍ່ມີຜົນສະທ້ອນເລີຍ, ວຽກ D ຄວນມອບໝາຍໃຫ້ຄົນອື່ນ ແລະ ວຽກ E ຄວນຕັດອອກ.$$),
    jsonb_build_object('type', $$list$$, 'items', jsonb_build_array(
    jsonb_build_object('label', $$ວຽກ A$$, 'body', $$ມີຜົນສະທ້ອນຮ້າຍແຮງ ບໍ່ວ່າດີ ຫຼື ບໍ່ດີ ຕິດຢູ່ນຳການເຮັດ ຫຼື ບໍ່ເຮັດ. ຖ້າມີວຽກ A ຫຼາຍກວ່າໜຶ່ງ ໃຫ້ຈັດອັນດັບເປັນ A-1, A-2, A-3 ຕາມຄວາມສຳຄັນ ແລະ A-1 ຄືກົບຂອງທ່ານ.$$),
    jsonb_build_object('label', $$ວຽກ B$$, 'body', $$ມີຜົນສະທ້ອນທີ່ບໍ່ຄ່ອຍພໍໃຈ ຫາກຂ້າມໄປ — ວຽກທີ່ຄວນເຮັດ ແຕ່ບໍ່ຄວນເຮັດແທນວຽກ A ໂດຍເດັດຂາດ.$$),
    jsonb_build_object('label', $$ວຽກ C$$, 'body', $$ບໍ່ມີຜົນສະທ້ອນທັງສອງທາງ. ຕົວຢ່າງຂອງ Tracy ຄື ການດື່ມກາເຟຄຸຍນຳເພື່ອນຮ່ວມງານ — ໜ້າພໍໃຈ ແຕ່ບໍ່ກ່ຽວກັບຜົນລັບ.$$),
    jsonb_build_object('label', $$ວຽກ D$$, 'body', $$ຄວນເຮັດ ແຕ່ບໍ່ຈຳເປັນຕ້ອງເປັນທ່ານ — ມອບໝາຍໃຫ້ຄົນອື່ນເພື່ອປົດປ່ອຍເວລາໃຫ້ວຽກ A.$$),
    jsonb_build_object('label', $$ວຽກ E$$, 'body', $$ຕັດອອກທັງໝົດ. ມັກເປັນກິດຈະກຳຕິດນິໄສ ທີ່ຍັງຄົງຢູ່ພຽງເພາະບໍ່ມີໃຜເຄີຍຖາມວ່າມັນຍັງຈຳເປັນຢູ່ບໍ.$$)
  )),
    jsonb_build_object('type', $$p$$, 'text', $$ກົດທີ່ເຮັດໃຫ້ວິທີນີ້ໄດ້ຜົນ ແລະ ເປັນກົດທີ່ຄົນມັກລະເມີດທີ່ສຸດ ຄືງ່າຍໆ: ຢ່າແຕະຕ້ອງວຽກ B ໃນຂະນະທີ່ວຽກ A ຍັງບໍ່ທັນສຳເລັດ. ຂໍ້ສັງເກດຂອງ Tracy ຄື ວຽກ B ມັກສະດວກກວ່າໃນການເຮັດ — ນັ້ນແຫຼະຄືກັບດັກທີ່ເຮັດໃຫ້ວຽກ A ທີ່ສຳຄັນແທ້ໆ ຄ່ອຍໆເລື່ອນໄປມື້ອື່ນຢ່າງງຽບໆ ໃນຂະນະທີ່ຄົນຄົນນັ້ນຍັງຮູ້ສຶກວ່າຕົນມີຜົນຜະລິດຢູ່.$$)
