    jsonb_build_object('term', $$Fractional reserve banking$$, 'body', $$Holding only a portion of deposited money in reserve while lending out or issuing claims against the rest.$$),
    jsonb_build_object('term', $$Classical gold standard$$, 'body', $$A system where national currencies were defined as a fixed weight of gold and freely convertible into it.$$),
    jsonb_build_object('term', $$Bretton Woods system$$, 'body', $$The 1944 arrangement that pegged the US dollar to gold and pegged other major currencies to the dollar.$$),
    jsonb_build_object('term', $$Fiat money$$, 'body', $$Currency not backed by a scarce commodity, whose value rests on government decree and user confidence.$$),
    jsonb_build_object('term', $$Eurodollar$$, 'body', $$Dollar-denominated deposits and credit created and held largely outside the direct regulatory reach of the US banking system.$$),
    jsonb_build_object('term', $$Double-spend problem$$, 'body', $$The risk that the same digital token could be copied and spent more than once without a mechanism to prevent it.$$),
    jsonb_build_object('term', $$Proof of work$$, 'body', $$A mechanism requiring real, verifiable computational effort to add new transactions, making history costly to rewrite.$$)
